import {
  createPanZoom,
  type PanZoom as PanZoomController,
  type PanZoomPoint,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createSignal, merge, untrack } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };
import { createPanzoomGlide, type FrameScheduler, type PanzoomGlide } from "./panzoom-glide.ts";

export interface PanzoomProps {
  /** The image: a URL, or a `data:` URI. */
  readonly src: string;
  /** The image's text alternative; the viewport's own name is `label`. */
  readonly alt: string;
  /** Its natural width, for the frame's shape; read from the image when both are left out. */
  readonly width?: number;
  /** Its natural height, for the frame's shape; read from the image when both are left out. */
  readonly height?: number;
  /** The viewport's accessible name: what the image shows, in the page's words (default `"Image"`). */
  readonly label?: string;
  /** The line under the frame; left out, the gestures and the keys in one sentence. */
  readonly hint?: string;
  /** Smallest scale, and where reset returns. @default 1 */
  readonly min?: number;
  /** Largest scale. @default 4 */
  readonly max?: number;
  /** The zoom buttons' and `+` / `-`'s increment. @default 0.25 */
  readonly step?: number;
  /** Starting scale when uncontrolled; ignored while `scale` is set. */
  readonly defaultScale?: number;
  /** Controlled: the host owns the scale and this is the only thing that changes it. */
  readonly scale?: number;
  readonly onScaleChange?: (scale: number) => void;
  readonly onPanChange?: (offset: PanZoomPoint) => void;
  /** `"clamp"` (default) keeps the scaled image covering the frame; `"free"` lets it leave. */
  readonly bounds?: "clamp" | "free";
  /** `prefers-reduced-motion: reduce`: a flick lands where the drag left it, with no glide. */
  readonly reducedMotion?: boolean;
  readonly class?: string;
  /** The primitive, once: a page that reads `scale()` or drives the camera. */
  readonly onReady?: (panzoom: PanZoomController) => void;
  /** The glide machine, once: a fixture sends a stale frame or reads the phase; a page rarely does. */
  readonly onGlide?: (glide: PanzoomGlide) => void;
  /** The glide's frame loop; the browser's by default, a test's queue in a test. */
  readonly frames?: FrameScheduler;
}

const DEFAULT_HINT =
  "Drag or flick to pan, pinch or Ctrl/⌘ + wheel to zoom. Keys: +, -, arrows and 0.";

/** The window a release's velocity is measured over: the last 100 ms of pointer samples. */
const GLIDE_VELOCITY_WINDOW = 100;
/** A shorter interval than this is not a velocity: a burst of synthetic moves in one task would read as a flick. */
const GLIDE_VELOCITY_FLOOR = 8;

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2), css.width("100%"));

// The frame is the box the primitive's maths assumes: the image fills it at `min` (object-fit: cover), its origin is the
// centre, and the clips are the rounded corners. `touch-action: none` is the touch drag; the pointer is the only gesture
// the primitive cannot replace with a key, so it is the only one the skin has to allow through.
const viewportClass = css.cn(
  css.position("relative"),
  css.display("block"),
  css.width("100%"),
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.bg(t.color.surface),
  css.touchAction("none"),
  css.userSelect("none"),
  css.cursor("grab"),
  css.outline("none"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.attr("data-dragging", "true")(css.cursor("grabbing")),
);

// The transform is the primitive's, inline: the transition is the skin's, and only for a reader who allows motion. A drag
// sets `data-dragging` on the image, and the attribute's higher specificity drops the transition while the pointer moves,
// so the picture follows the pointer instead of trailing it.
const imageClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.width("100%"),
  css.height("100%"),
  css.objectFit("cover"),
  css.transformOrigin("50% 50%"),
  css.userSelect("none"),
  css.pointerEvents("none"),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("transform 140ms ease-out"),
    css.attr("data-dragging", "true")(css.transition("none")),
    // the glide writes the transform on every frame: a transition would make it trail its own velocity
    css.within(css.attr("data-gliding", "true"))(css.transition("none")),
  ),
);

const barClass = css.cn(
  css.display("flex"),
  css.flexWrap("wrap"),
  css.alignItems("center"),
  css.justifyContent("space-between"),
  css.gap(t.space._2),
);

// The live region is visible, not hidden: the zoom is a number a reader may want to read, and a region that is on screen is
// also a region a screen reader has been watching.
const valueClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.fontVariantNumeric("tabular-nums"),
  css.color(t.color.text),
  css.minWidth(t.space._7),
);

const controlsClass = css.cn(css.display("flex"), css.flexWrap("wrap"), css.gap(t.space._2));

const hintClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

/**
 * One image in a frame, styled: `createPanZoom` owns the scale, the offset, the pointer drag and pinch, the wheel, the
 * double click, the keys (+, -, arrows, 0) and the live value the viewport describes; the skin owns the surface and its
 * rounded corners, the focus ring, the value and the three buttons, the hint, and the glide.
 *
 * A fast flick leaves the picture moving: the pointer's last 100 ms are measured on release, and `panzoom-glide.ts` runs
 * the momentum as a machine — one frame per effect, `panBy` on the primitive, a grab that takes the picture back from
 * the frame it is on, a key or a double click that stops it, and no loop at all under reduced motion. The offset stays
 * the primitive's; the machine carries the velocity and `data-gliding` reads the phase.
 *
 * The frame's shape comes from `width` / `height` (or the image's own natural size once it loads), and the image fills it
 * with `object-fit: cover`, which is what the primitive's clamp assumes. A page that needs a letterboxed image passes
 * `bounds="free"`.
 */
export const Panzoom = (props: PanzoomProps): JSX.Element => {
  const panzoom = createPanZoom({
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get step() {
      return props.step;
    },
    defaultScale: props.defaultScale,
    get scale() {
      return props.scale;
    },
    get bounds() {
      return props.bounds;
    },
    get onScaleChange() {
      return props.onScaleChange;
    },
    get onPanChange() {
      return props.onPanChange;
    },
    get labels() {
      return props.label === undefined ? undefined : { viewport: props.label };
    },
  });
  // a structural prop, read once: it is the primitive for a page, not a signal
  untrack(() => props.onReady)?.(panzoom);

  // The glide is the skin's: the primitive owns the drag and the offset, and has no way to move the pan from outside,
  // so it gains `panBy` for this. The machine's context is the velocity only.
  const glide = createPanzoomGlide({
    panzoom,
    reducedMotion: untrack(() => props.reducedMotion),
    frames: untrack(() => props.frames),
  });
  untrack(() => props.onGlide)?.(glide);

  // Velocity sampling is the skin's, not the primitive's: the last 100 ms of pointer samples decide a fling, a hold
  // before the lift is no velocity, and a second pointer is a pinch, not a flick.
  const samples: { at: number; x: number; y: number }[] = [];
  const pointers = new Set<number>();
  let pinched = false;

  const sample = (event: PointerEvent): void => {
    samples.push({ at: event.timeStamp, x: event.clientX, y: event.clientY });
    while (samples.length > 1) {
      const head = samples[0];
      if (head === undefined || event.timeStamp - head.at <= GLIDE_VELOCITY_WINDOW) {
        break;
      }
      samples.shift();
    }
  };

  /** The release's velocity, in px/ms: the window's own span, or none when the pointer rested before it lifted. */
  const velocity = (timeStamp: number): PanZoomPoint => {
    const head = samples[0];
    const tail = samples.at(-1);
    const age = tail === undefined ? Number.POSITIVE_INFINITY : timeStamp - tail.at;
    const elapsed = head === undefined || tail === undefined ? 0 : tail.at - head.at;
    if (
      age > GLIDE_VELOCITY_WINDOW ||
      elapsed <= GLIDE_VELOCITY_FLOOR ||
      head === undefined ||
      tail === undefined
    ) {
      return { x: 0, y: 0 };
    }
    return { x: (tail.x - head.x) / elapsed, y: (tail.y - head.y) / elapsed };
  };

  // the natural size, until the image has loaded and told us; 16:10 is the shape of a frame with nothing to go on
  const [natural, setNatural] = createSignal({ width: 16, height: 10 });
  const size = () => ({
    width: props.width ?? natural().width,
    height: props.height ?? natural().height,
  });
  const readNatural = (event: Event & { readonly currentTarget: HTMLImageElement }): void => {
    const image = event.currentTarget;
    if (image.naturalWidth > 0 && image.naturalHeight > 0) {
      setNatural({ width: image.naturalWidth, height: image.naturalHeight });
    }
  };

  // The skin's own bit of drag state: the primitive owns the gesture, this only says the pointer is down, for the cursor
  // and for the transition.
  const [dragging, setDragging] = createSignal(false);

  const viewport = merge(panzoom.viewportProps, {
    "data-part": "panzoom-viewport",
    get "data-dragging"() {
      return dragging() ? "true" : undefined;
    },
    get "data-gliding"() {
      return glide.gliding() ? "true" : undefined;
    },
    get style() {
      const { width, height } = size();
      // kebab-case: Solid's style helper sets every key with `setProperty`, which ignores a camelCase name
      return { "aspect-ratio": `${width} / ${height}` };
    },
    get class() {
      return viewportClass;
    },
    onPointerDown: (event: PointerEvent) => {
      // the grab takes the picture before the primitive snapshots the offset for the drag: no frame can land between
      glide.grab();
      setDragging(true);
      if (event.button !== 0) {
        panzoom.viewportProps.onPointerDown(event);
        return;
      }
      if (pointers.size === 0) {
        pinched = false;
        samples.length = 0;
      }
      pointers.add(event.pointerId);
      if (pointers.size > 1) {
        pinched = true;
      }
      sample(event);
      panzoom.viewportProps.onPointerDown(event);
    },
    onPointerMove: (event: PointerEvent) => {
      if (pointers.has(event.pointerId)) {
        sample(event);
      }
      panzoom.viewportProps.onPointerMove(event);
    },
    onPointerUp: (event: PointerEvent) => {
      setDragging(false);
      panzoom.viewportProps.onPointerUp(event);
      pointers.delete(event.pointerId);
      if (pointers.size > 0) {
        // a finger remains: the gesture continues, and a pinch never ends in a fling
        return;
      }
      const released = !pinched && samples.length > 0 ? velocity(event.timeStamp) : undefined;
      pinched = false;
      samples.length = 0;
      if (released !== undefined) {
        glide.fling(released.x, released.y);
      }
    },
    onPointerCancel: (event: PointerEvent) => {
      setDragging(false);
      panzoom.viewportProps.onPointerCancel(event);
      pointers.delete(event.pointerId);
      if (pointers.size === 0) {
        pinched = false;
        samples.length = 0;
      }
    },
    onKeyDown: (event: KeyboardEvent) => {
      // the reader took over: a key ends the glide where it is, before the primitive moves the picture
      if (glide.gliding()) {
        glide.stop();
      }
      panzoom.viewportProps.onKeyDown(event);
    },
    onDblClick: (event: MouseEvent) => {
      // a reset is a take-over too: the glide must not carry the picture away from where reset put it
      if (glide.gliding()) {
        glide.stop();
      }
      panzoom.viewportProps.onDblClick(event);
    },
  } as PartProps);

  const image = merge(panzoom.imageProps, {
    "data-part": "panzoom-image",
    get "data-dragging"() {
      return dragging() ? "true" : undefined;
    },
    get class() {
      return imageClass;
    },
  } as PartProps);

  return (
    <div data-part="panzoom" class={css.cn(rootClass, props.class)}>
      <div {...viewport}>
        <img
          {...image}
          alt={props.alt}
          src={props.src}
          width={size().width}
          height={size().height}
          onLoad={readNatural}
        />
      </div>
      <div data-part="panzoom-bar" class={barClass}>
        <span {...panzoom.valueProps} data-part="panzoom-value" class={valueClass}>
          {panzoom.value()}
        </span>
        <div data-part="panzoom-controls" class={controlsClass}>
          <Button size="sm" tone="quiet" onClick={panzoom.zoomOut}>
            Zoom out
          </Button>
          <Button size="sm" tone="quiet" onClick={panzoom.zoomIn}>
            Zoom in
          </Button>
          <Button size="sm" tone="quiet" onClick={panzoom.reset}>
            Reset
          </Button>
        </div>
      </div>
      <p data-part="panzoom-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

// The glide of the pan-zoom skin: a flick leaves the picture moving, and a grab takes it back. It is a machine rather
// than a `requestAnimationFrame` in the component because the races are the protocol: a pointer down during the glide
// must own the picture from the frame the last tick wrote (`ReversalKeepsPosition`), a frame that outlives its effect
// must move nothing (`StaleCarriesCancelled`), a reader's key must end the animation, an unmount must cancel the loop,
// and reduced motion must never start one. Those are asserted on `@cssints/machine`'s harness without a browser, and
// the same machine is what the DOM test drives.
//
// The offset stays in `@cssints/headless`'s primitive: it already holds it, clamps it and reports it through
// `onPanChange`. The machine carries only the velocity (`vx`, `vy` in px/ms) and its phase, so the store is read for
// `data-gliding` and the offset never goes through it.
import { type ConfigEvent, createMachine, defineMachine, type Machine } from "@cssints/machine";
import { type MachineStore, createMachineStore } from "@cssints/machine/solid";
import type { PanZoom } from "@cssints/headless";
import { type Accessor, onCleanup, untrack } from "solid-js";

/** How fast a release must be, in px/ms, to leave a glide: 0.3 is a deliberate flick, not a drag. */
export const PANZOOM_FLING_VELOCITY = 0.3;
/** The speed at which a glide is over, in px/ms. */
export const PANZOOM_GLIDE_FLOOR = 0.02;
// Per frame, not per millisecond: the machine has no clock in an `assign`, and a frame is its tick. At 60 Hz a flick of
// 1 px/ms travels about 200 px and is over in about 650 ms; a 120 Hz display halves both. `ponytail:` one multiplier for
// every display; pass each frame's elapsed time if a real trackpad needs the same distance on a 120 Hz screen.
const PANZOOM_GLIDE_FRICTION = 0.92;

/** The glide's phases: still, or the picture is moving under its own momentum. */
export type PanzoomGlidePhase = "rest" | "gliding";

/** The glide's context: the velocity the last tick moved the picture by, in px/ms. */
export interface PanzoomGlideContext {
  readonly vx: number;
  readonly vy: number;
}

// a type alias, not an interface: `PayloadMap` is an index signature, and only an alias is assignable to one
type PanzoomGlidePayloads = {
  readonly fling: { readonly vx: number; readonly vy: number };
  readonly grab: undefined;
  readonly frame: { readonly id: number };
  readonly stop: undefined;
};

/** The glide's events: a release's velocity, the pointer's grab, one animation frame and a take-over. */
export type PanzoomGlideEvent =
  | { readonly type: "fling"; readonly vx: number; readonly vy: number }
  | { readonly type: "grab" }
  | { readonly type: "frame"; readonly id: number }
  | { readonly type: "stop" };

/** The running glide machine, as the skin and its tests name it. */
export type PanzoomGlideMachine = Machine<
  PanzoomGlideContext,
  PanzoomGlidePhase,
  PanzoomGlideEvent
>;

type PanzoomGlideConfig = ConfigEvent<PanzoomGlidePayloads>;

const ZERO: PanzoomGlideContext = { vx: 0, vy: 0 };

const speedOf = (event: PanzoomGlideConfig): number =>
  event.type === "fling" ? Math.hypot(event.vx, event.vy) : 0;

const velocityOf = (event: PanzoomGlideConfig): PanzoomGlideContext =>
  event.type === "fling" ? { vx: event.vx, vy: event.vy } : ZERO;

/**
 * The glide protocol as data, for the skin and for a harness. `rest` holds still; a `fling` fast enough to matter
 * enters `gliding` with one `glide` effect; every `frame` is one tick, which re-enters `gliding` (the state's effect is
 * the next frame, so a landing frame is also a cancel) and decays the velocity; a `grab` or a `stop` takes the picture
 * back to `rest` and cancels the pending frame.
 *
 * `frame` carries the effect's handle id, so a tick that the machine no longer owns (a grab happened, the effect was
 * replaced) is dropped before any transition is looked at. Under reduced motion a release lands at `rest` in one step
 * and no effect is issued: there is no loop to cancel because there never was one.
 */
export const panzoomGlideDefinition = (reduced: boolean) =>
  defineMachine<PanzoomGlidePayloads>()({
    start: "rest",
    initial: ZERO,
    states: {
      rest: {
        on: {
          fling: [
            {
              // a slow release is not a flick, and reduced motion never glides
              guard: (_context, event) => reduced || speedOf(event) < PANZOOM_FLING_VELOCITY,
              target: "rest",
              assign: ZERO,
            },
            {
              target: "gliding",
              assign: (_context, event) => velocityOf(event),
            },
          ],
          grab: { target: "rest", assign: ZERO },
          stop: { target: "rest", assign: ZERO },
        },
      },
      gliding: {
        // every tick re-enters this state, so the frame that lands also owns the cancellation of the loop
        effect: [{ type: "glide" }],
        on: {
          frame: {
            target: "gliding",
            assign: (context) => ({
              vx: context.vx * PANZOOM_GLIDE_FRICTION,
              vy: context.vy * PANZOOM_GLIDE_FRICTION,
            }),
          },
          grab: { target: "rest", assign: ZERO },
          stop: { target: "rest", assign: ZERO },
        },
      },
    },
  });

/** One frame's scheduler: `requestAnimationFrame` in a browser, a queue in a test. */
export interface FrameScheduler {
  request(callback: (time: number) => void): number;
  cancel(handle: number): void;
}

/** The browser's own frame loop. */
export const browserFrames: FrameScheduler = {
  request: (callback) => requestAnimationFrame(callback),
  cancel: (handle) => cancelAnimationFrame(handle),
};

/** The pan the glide moves: the primitive's offset and the relative pan it clamps. */
export type PanzoomGlideTarget = Pick<PanZoom, "offset" | "panBy">;

/** What the glide needs: the primitive, the motion preference and the frame scheduler a test supplies. */
export interface PanzoomGlideOptions {
  readonly panzoom: PanzoomGlideTarget;
  /** `prefers-reduced-motion: reduce` (or the override); left out, it is read once. */
  readonly reducedMotion?: boolean | undefined;
  /** The frame loop; the browser's by default, a queue in a test. */
  readonly frames?: FrameScheduler | undefined;
}

/** The glide as the skin reads it: the machine, its store, the phase and the three intents. */
export interface PanzoomGlide {
  readonly machine: PanzoomGlideMachine;
  readonly store: MachineStore<PanzoomGlideContext, PanzoomGlidePhase, PanzoomGlideEvent>;
  /** The picture is moving by itself: `data-gliding`. */
  readonly gliding: Accessor<boolean>;
  /** A release's velocity, in px/ms; the machine drops it below the threshold or under reduced motion. */
  readonly fling: (vx: number, vy: number) => void;
  /** A pointer down: the glide's effect is cancelled and the drag continues from the offset the last frame wrote. */
  readonly grab: () => void;
  /** The reader took over (a key, a double click): the glide stops where it is. */
  readonly stop: () => void;
}

const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * Run the glide of one picture. Call it in a component body, beside `createPanZoom`: the store and the cleanup belong
 * to the component.
 *
 * Each effect is one frame: the host reads the velocity, asks the primitive for `panBy(vx * dt, vy * dt)`, and either
 * sends the tick and decays or sends `stop` when the clamp swallowed the move or the friction floor was reached. The
 * effect of a landing tick is cancelled with the state, so the loop ends at rest rather than at a final frame nobody
 * owns.
 */
export const createPanzoomGlide = (options: PanzoomGlideOptions): PanzoomGlide => {
  const frames = options.frames ?? browserFrames;
  const reduced = untrack(() => options.reducedMotion) ?? prefersReducedMotion();
  const machine: PanzoomGlideMachine = createMachine(panzoomGlideDefinition(reduced));
  const store = createMachineStore(machine);

  /** The id of the handle the pending frame belongs to; `undefined` when nothing is pending. */
  let current: number | undefined;
  let pending: number | undefined;
  /** The previous frame's timestamp, for the distance this one travels. */
  let last: number | undefined;

  const cancelPending = (): void => {
    if (pending !== undefined) {
      frames.cancel(pending);
      pending = undefined;
    }
  };

  const offEffect = machine.onEffect((handle) => {
    if (handle.type !== "glide") {
      return;
    }
    current = handle.id;
    pending = frames.request((time) => {
      pending = undefined;
      // a frame already dispatched when its effect was cancelled moves nothing: the picture belongs to the grab
      if (current !== handle.id) {
        return;
      }
      const { vx, vy } = machine.getState().context;
      // a stalled tab hands over one at most 64 ms long step, not a jump across the picture
      const dt = last === undefined ? 16.7 : Math.min(64, Math.max(1, time - last));
      last = time;
      if (Math.hypot(vx, vy) < PANZOOM_GLIDE_FLOOR) {
        machine.send({ type: "stop" });
        return;
      }
      const before = options.panzoom.offset();
      options.panzoom.panBy(vx * dt, vy * dt);
      const after = options.panzoom.offset();
      if (after.x === before.x && after.y === before.y) {
        // the clamp has the picture: a glide that pushed into it is over, at the bound
        machine.send({ type: "stop" });
        return;
      }
      machine.send({ type: "frame", id: handle.id });
    });
  });

  const offCancel = machine.onCancel((handle) => {
    if (current !== handle.id) {
      return;
    }
    current = undefined;
    cancelPending();
  });

  const fling = (vx: number, vy: number): void => {
    last = undefined;
    machine.send({ type: "fling", vx, vy });
  };

  const grab = (): void => {
    last = undefined;
    machine.send({ type: "grab" });
  };

  const stop = (): void => {
    last = undefined;
    machine.send({ type: "stop" });
  };

  onCleanup(() => {
    // `destroy` cancels the handles, but the listeners are gone by then: the loop is cancelled here, while it can be
    cancelPending();
    current = undefined;
    offEffect();
    offCancel();
    machine.destroy();
  });

  return {
    machine,
    store,
    gliding: () => store.state.phase === "gliding",
    fling,
    grab,
    stop,
  };
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

